function h(?string $v):string{return htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}
function coach_columns(PDO $pdo): void
{
    $columns = array_column($pdo->query('PRAGMA table_info(coaches)')->fetchAll(), 'name');
    $additions = [
        'education' => "TEXT NOT NULL DEFAULT ''",
        'qualification' => "TEXT NOT NULL DEFAULT ''",
        'academic_degree' => "TEXT NOT NULL DEFAULT ''",
        'academic_title' => "TEXT NOT NULL DEFAULT ''",
        'professional_development' => "TEXT NOT NULL DEFAULT ''",
        'professional_retraining' => "TEXT NOT NULL DEFAULT ''",
        'experience_text' => "TEXT NOT NULL DEFAULT ''",
        'visible' => 'INTEGER NOT NULL DEFAULT 1',
    ];
    foreach ($additions as $column => $definition) {
        if (!in_array($column, $columns, true)) $pdo->exec("ALTER TABLE coaches ADD COLUMN $column $definition");
    }
}

function upload_file(array $f,string $folder,array $exts):string{if(($f['error']??UPLOAD_ERR_NO_FILE)===UPLOAD_ERR_NO_FILE)return '';if(($f['error']??0)!==UPLOAD_ERR_OK||($f['size']??0)>104857600)throw new RuntimeException('Ошибка загрузки или файл превышает 100 МБ.');$ext=strtolower(pathinfo((string)$f['name'],PATHINFO_EXTENSION));if(!in_array($ext,$exts,true))throw new RuntimeException('Недопустимый формат файла.');$r='uploads/'.$folder.'/'.bin2hex(random_bytes(16)).'.'.$ext;if(!move_uploaded_file($f['tmp_name'],dirname(__DIR__).'/'.$r))throw new RuntimeException('Не удалось сохранить файл.');return $r;}
